<?php
require "config.php";
function cn($s){$n=0;foreach(str_split(strtoupper($s)) as $c)$n=$n*26+ord($c)-64;return $n-1;}
function xlsx($f){$z=new ZipArchive();if($z->open($f)!==true)throw new Exception("No se pudo abrir el XLSX.");$ss=[];$a=$z->getFromName("xl/sharedStrings.xml");if($a!==false){$x=simplexml_load_string($a);foreach($x->si as $i){$t="";if(isset($i->t))$t=(string)$i->t;else foreach($i->r as $r)$t.=(string)$r->t;$ss[]=$t;}}$a=$z->getFromName("xl/worksheets/sheet1.xml");if($a===false)throw new Exception("No se encontró la primera hoja.");$x=simplexml_load_string($a);$o=[];foreach($x->sheetData->row as $row){$d=[];foreach($row->c as $c){preg_match('/([A-Z]+)/',(string)$c["r"],$m);$v=isset($c->v)?(string)$c->v:"";if((string)$c["t"]==="s")$v=$ss[(int)$v]??"";elseif((string)$c["t"]==="inlineStr")$v=(string)$c->is->t;$d[cn($m[1])]=$v;}$o[]=$d;}$z->close();return $o;}
$msg="";$err="";if($_SERVER["REQUEST_METHOD"]==="POST"){try{if($_FILES["excel"]["error"]!==UPLOAD_ERR_OK)throw new Exception("Seleccione un archivo.");if(strtolower(pathinfo($_FILES["excel"]["name"],PATHINFO_EXTENSION))!=="xlsx")throw new Exception("Use un archivo .xlsx.");$rows=xlsx($_FILES["excel"]["tmp_name"]);$h=[];foreach($rows[0] as $k=>$v)$h[strtolower(trim($v))]=$k;if(!isset($h["nombre"])||!isset($h["apellido"]))throw new Exception("Faltan las columnas nombre y apellido.");$s=$conexion->prepare("INSERT INTO certificados(nombre,apellido,ci,correo,programa,fecha_emision,codigo) VALUES(?,?,?,?,?,?,?)");$n=0;for($i=1;$i<count($rows);$i++){$r=$rows[$i];$nom=trim($r[$h["nombre"]]??"");$ape=trim($r[$h["apellido"]]??"");if(!$nom&&!$ape)continue;if(!$nom||!$ape)continue;$ci=isset($h["ci"])?trim($r[$h["ci"]]??""):"";$correo=isset($h["correo"])?trim($r[$h["correo"]]??""):"";if($correo && !filter_var($correo,FILTER_VALIDATE_EMAIL))continue;$p=isset($h["programa"])?trim($r[$h["programa"]]??""):"GESTIÓN PÚBLICA Y DEFENSA LEGAL DEL ESTADO";if(!$p)$p="GESTIÓN PÚBLICA Y DEFENSA LEGAL DEL ESTADO";$f=isset($h["fecha_emision"])?trim($r[$h["fecha_emision"]]??""):"";$fecha=$f?date("Y-m-d",is_numeric($f)?strtotime("1899-12-30 +".(int)$f." days"):strtotime($f)):date("Y-m-d");$cod="PGE-".date("Y")."-".strtoupper(bin2hex(random_bytes(4)));$s->bind_param("sssssss",$nom,$ape,$ci,$correo,$p,$fecha,$cod);if($s->execute())$n++;}$s->close();$msg="Importados: $n";}catch(Throwable $e){$err=$e->getMessage();}}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Importar Excel</title><style>body{font-family:Arial;background:#eee;padding:30px}.box{max-width:650px;margin:auto;background:white;padding:30px;border-radius:12px}input{width:100%;padding:12px;box-sizing:border-box;margin:15px 0}button,a{padding:12px 18px;background:#9b741c;color:white;border:0;border-radius:6px;text-decoration:none}.ok{color:green}.err{color:red}</style></head><body><div class="box"><a href="index.php">← Menú</a><h2>Importar Excel</h2><?php if($msg):?><p class="ok"><?=$msg?></p><?php endif;?><?php if($err):?><p class="err"><?=htmlspecialchars($err)?></p><?php endif;?><form method="post" enctype="multipart/form-data"><input type="file" name="excel" accept=".xlsx" required><button>IMPORTAR EXCEL</button></form><p>Columnas: <b>nombre, apellido, ci, correo, programa, fecha_emision</b><br>La columna correo es opcional al importar, pero necesaria para enviar certificados.</p></div></body></html>